$ctrl.authCookies.setServerUrl($ctrl.$env.getProperty("payroll_api_base_url"));
const usrIsAdmin = await $ctrl.authService.redirectWorker();
if(!usrIsAdmin) return;

$ctrl.uiState.currentTab.name = "user";

// Restore retained page & filters
const savedFilter = $ctrl.userPreferenceService.get("peopleManagement", "userTabFilter", null);

if ($ctrl.pageParameters.page) {
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].currentPage = $ctrl.pageParameters.page;
}

if (savedFilter) {
    $ctrl.uiState.currentFilter.advancedFilters = savedFilter.advancedFilters || [];
    $ctrl.uiState.currentFilter.currentFilterString = savedFilter.currentFilterString || "";
    $ctrl.uiState.currentFilter.usingAdvancedFilters = !!savedFilter.usingAdvancedFilters;

    if ($ctrl.uiState.currentFilter.advancedFilters.length > 0) {
        $ctrl.filterOperationsService.updateFilterChips(
            $ctrl.uiState,
            $ctrl.tabConfig,
            $ctrl.referenceData
        );
    }
}


$ctrl.uiState.currentFilter.quickSearchPlaceholder = $ctrl.filterService.quickSearchConfig.getSearchPlaceholder(
    $ctrl.uiState.currentTab.name,
    $ctrl.tabConfig[$ctrl.uiState.currentTab.name].quickSearchDefaultConfig,
    $ctrl.userPreferenceService
);

$ctrl.loaders.loadActiveTab();
$ctrl.loaders.loadReferenceMaps();
$ctrl.loaders.loadFontAwesome();

