if (!params) params = {};

// Manually set loading states since baseGridControllerService will not handle it here
// This will be set to false either here or loadProfileTabContent (user table) or loadProfileGridData (profile mode)
$ctrl.uiState.isLoadingTable = true;

$ctrl.uiState.currentRequestId++;
const currentRequestId = $ctrl.uiState.currentRequestId;

const entityType = "user"; // Hardcoded main tab
const page = params.page || $ctrl.tabStore[entityType].currentPage;
const tabConfig = $ctrl.tabConfig[entityType];

let apiQuery = $ctrl.filterService.buildCombinedQuery({
    advancedFilters: $ctrl.uiState.currentFilter.advancedFilters
});

if (tabConfig?.companyBound) {
    apiQuery += `&CompanyId=${$ctrl.globalSelectedCompany.companyId}`;
}

try {
    // Wait for the primary grid data
    await $ctrl.baseGridControllerService.loadGridData($ctrl, {
        entityType,
        customEntityKey: tabConfig?.customEntityKey,
        columnDefs: tabConfig?.columnDefaultConfig,
        page,
        limit: $ctrl.tabStore[entityType].limit,
        query: apiQuery,
        resetUiState: !$ctrl.uiState.isViewingUserProfile,
        touchLoadingStates: false,
    });

    // If the user clicked away or searched again while the grid was loading, abort
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    // Load secondary data only if this is still the active request
    await $ctrl.loaders.loadAdditionalUserData();

    // If the user clicked away or searched while loading additional user data, abort
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    // Only set loading state to false if user is not viewing a profile
    if (!$ctrl.uiState.isViewingUserProfile) {
        $ctrl.uiState.isLoadingTable = false;
    }

} catch (err) {
    // Only log if it's the active request
    if (currentRequestId === $ctrl.uiState.currentRequestId) {
        console.error("Failed to load active tab data", err);
    }
}

const workerIds = $ctrl.tabStore.user.data
    .map(u => u.WorkerId).filter(id => id);

if (!workerIds || workerIds.length === 0) return;

try {
    const workerIdFilter = `WorkerId_in=${workerIds.join(',')}`;
    const [employmentInfoRes, workerPositionRes] = await Promise.all([
        $ctrl.payrollApiService.get({
            entity: "employment_info",
            limit: workerIds.length,
            query: `${workerIdFilter}&select=Id,WorkerId,EmploymentStartDate`,
            customEntityKey: "employmentinfo"
        }),
        $ctrl.payrollApiService.get({
            entity: "worker_position",
            limit: workerIds.length,
            query: `${workerIdFilter}&select=Id,WorkerId,PositionId,CustomAnnualRate`,
            customEntityKey: "workerposition"
        })
    ]);

    const employmentInfos = employmentInfoRes.entities || employmentInfoRes || [];
    const workerPositions = workerPositionRes.entities || workerPositionRes || [];

    // $ctrl.tabStore.worker_position.data = workerPositions;

    const positionIds = [...new Set(workerPositions.map(wp => wp.PositionId).filter(id => id))];
    let positions = [];

    if (positionIds.length > 0) {
        const positionRes = await $ctrl.payrollApiService.get({
            entity: "position",
            limit: positionIds.length,
            query: `Id_in=${positionIds.join(',')}&select=Id,Department,Title`
        });
        positions = positionRes.entities || positionRes || [];
    }

    const employmentMap = new Map(employmentInfos.map(ei => [ei.WorkerId, ei]));
    const workerPositionMap = new Map(workerPositions.map(wp => [wp.WorkerId, wp]));
    const positionMap = new Map(positions.map(p => [p.Id, p]));

    $ctrl.tabStore.user.data.forEach(user => {
        if (!user.WorkerId) return;

        const empInfo = employmentMap.get(user.WorkerId);
        if (empInfo) {
            user.EmploymentStartDate = empInfo.EmploymentStartDate;
        }

        const wp = workerPositionMap.get(user.WorkerId);
        if (wp && wp.PositionId) {
            const pos = positionMap.get(wp.PositionId);
            if (pos) {
                user.Title = pos.Title;
                user.Department = pos.Department;
                user.PositionId = pos.Id;
                user.CustomAnnualRate = wp.CustomAnnualRate;
            }
        }
    });

} catch (err) {
    console.error("Failed to load additional user data", err);
    $ctrl.utils.toast("Failed to load complete user profiles", "ERROR");
}

// Append Font Awesome link if not already present
if (!document.querySelector('link[href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css"]')) {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css';
    document.head.appendChild(link);
}

// Fetch formatted options directly from service
const companyOpts = await $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Company");

// Update Global Menu
if ($ctrl.globalSelectedCompany) {
    $ctrl.globalSelectedCompany.companyMap = companyOpts;
    $ctrl.globalSelectedCompany.setMenuItems();
}

const config = $ctrl.tabConfig[$ctrl.uiState.currentTab.name];
if (!config) {
    console.error("No configuration found for current tab:", $ctrl.uiState.currentTab.name);
    return;
}

const isCreate = $ctrl.uiState.isCreatingNewEntity;
const entityType = $ctrl.uiState.currentTab.name;

const isUser = entityType === "user";

const method = "POST";
const formData = $ctrl[config.form];

let displayName = "Item";
if (config.getName) {
    displayName = config.getName(formData);
} else if (config.entityNameKey) {
    displayName = formData[config.entityNameKey] || "Item";
}

const additionalData = {};

$ctrl.uiState.isSaving = true;

await $ctrl.entityOperationsService.executeEntityOperation(
    method,
    formData,
    async (result) => {
        if (isUser) {
            const newUserId = result?.data?.user?.Id;

            if (newUserId) {
                const ROLES = { WORKER: 1, ADMIN: 2 };
                const rolePromises = [];

                if (formData.isWorker) {
                    rolePromises.push($ctrl.payrollApiService.send('user_role', 'POST', {
                        RoleId: ROLES.WORKER,
                        UserId: newUserId
                    }));
                }

                if (formData.isPayrollAdmin) {
                    rolePromises.push($ctrl.payrollApiService.send('user_role', 'POST', {
                        RoleId: ROLES.ADMIN,
                        UserId: newUserId
                    }));
                }

                if (rolePromises.length > 0) {
                    try {
                        await Promise.all(rolePromises);
                    } catch (err) {
                        console.error("Failed to assign user roles", err);
                        $ctrl.utils.toast("User created, but failed to assign one or more roles.", "WARNING");
                    }
                }
            } else {
                console.error("Could not determine new user Id to assign roles.");
            }
        }

        $ctrl.loaders.loadActiveTab();
        $ctrl.formManagementService.onFormClose($ctrl.uiState);
        $ctrl.utils.resetForm(formData);
    },
    null,
    () => {
        $ctrl.uiState.isSaving = false;
    },
    $ctrl.uiState.currentTab.name,
    displayName,
    $ctrl.uiState.selectedEntity
);

const formStatus = $ctrl.uiState.isCreatingNewEntity || $ctrl.uiState.isEditingExistingEntity;
if (formStatus) {    
    const discardChanges = await $ctrl.utils.handleUnsavedChanges(formStatus);
    if (!discardChanges) return;
}

$ctrl.$state.go("user", {userId: row.Id, retainPage: $ctrl.tabStore[$ctrl.uiState.currentTab.name].currentPage});
return;
